  const out = [];
  let v = 72.3;
  for (let y = 1996; y <= 2026; y++) {
    const months = y === 2026 ? 6 : 12;
    for (let m = 1; m <= months; m++) {
      v = +(v * (1 + (0.0015 + ((y * 12 + m) % 7) * 0.0003))).toFixed(2);
      out.push({
        date: `${y}-${String(m).padStart(2, '0')}-01`,
        value: v,
      });
    }
  }
  return out;
}

() => {
